rules.logic:
if (element.dataset.categoryTagsAdded) return;
element.dataset.categoryTagsAdded = "true";

var tagContainer = document.createElement("div");
tagContainer.className = "flex flex-wrap gap-2 mt-1 mb-3 category-tags-bar";

var tags = [
  { label: "Space", href: "/space" },
  { label: "Astronomy", href: "/astronomy" },
  { label: "Exoplanets", href: "/exoplanets" },
  { label: "NASA", href: "/nasa" },
  { label: "Hubble Telescope", href: "/hubble-telescope" }
];

tags.forEach(function(tag) {
  var link = document.createElement("a");
  link.href = tag.href;
  link.textContent = tag.label;
  link.className = "inline-block px-3 py-1 text-xs font-bold rounded-full bg-blue-600 text-white no-underline hover:bg-blue-700 transition-colors duration-200 shadow-sm";
  link.style.borderRadius = "9999px";
  link.style.whiteSpace = "nowrap";
  tagContainer.appendChild(link);
});

element.parentNode.insertBefore(tagContainer, element.nextSibling);
